export const RESOURCES=['wood','brick','grain','ore'];
const fail=m=>{throw Error(m);};
export function validateSettlement(raw,objects){
 const c=structuredClone(raw),ids=new Map(objects.map(o=>[o.id,o]));
 if(!Array.isArray(c.tiles)||c.tiles.length<7||c.tiles.length>37||new Set(c.tiles.map(t=>t.id)).size!==c.tiles.length)fail('Island games need 7–37 unique hex tiles.');
 const coords=new Set();c.tiles.forEach(t=>{if(ids.get(t.id)?.type!=='space'||!Number.isInteger(t.q)||!Number.isInteger(t.r)||Math.abs(t.q)>4||Math.abs(t.r)>4||!RESOURCES.includes(t.resource)||!Number.isInteger(t.number)||t.number<1||t.number>6)fail('Invalid island tile.');const key=t.q+','+t.r;if(coords.has(key))fail('Island hex coordinates must be unique.');coords.add(key);});
 if(!Array.isArray(c.playerNames)||c.playerNames.length!==2||c.playerNames.some(s=>typeof s!=='string'||!s.trim()||s.length>40))fail('Island games need two player names.');
 if(!Array.isArray(c.playerColors)||c.playerColors.length!==2||c.playerColors.some(s=>!/^#[\da-f]{6}$/i.test(s)))fail('Choose two player colors.');
 if(!Array.isArray(c.starts)||c.starts.length!==2||c.starts[0]===c.starts[1]||c.starts.some(i=>!Number.isInteger(i)||i<0||i>=c.tiles.length))fail('Choose distinct starting hexes.');
 if(!Array.isArray(c.pawnIds)||c.pawnIds.length!==2||c.pawnIds[0]===c.pawnIds[1]||c.pawnIds.some(id=>ids.get(id)?.type!=='piece'))fail('Two settlement building components are needed.');
 if(!Number.isInteger(c.turnLimit)||c.turnLimit<12||c.turnLimit>80||c.turnLimit%2||!Number.isInteger(c.targetPoints)||c.targetPoints<3||c.targetPoints>12)fail('Island ending must be 3–12 points or 12–80 turns.');
 // Connectivity is explicit in axial coordinates, and geometry must agree.
 const tiles=c.tiles.map(t=>ids.get(t.id)),unit=tiles[0].width;
 const originX=tiles[0].x-Math.sqrt(3)/2*unit*(c.tiles[0].q+c.tiles[0].r/2),originZ=tiles[0].z-.75*unit*c.tiles[0].r;
 c.tiles.forEach((t,i)=>{if(Math.abs(tiles[i].x-(originX+Math.sqrt(3)/2*unit*(t.q+t.r/2)))>.15||Math.abs(tiles[i].z-(originZ+.75*unit*t.r))>.15)fail('Island geometry must follow its axial hex coordinates.');});
 const reached=new Set([0]);for(let pass=0;pass<c.tiles.length;pass++)c.tiles.forEach((t,i)=>{if([...reached].some(j=>adjacent(c,i,j)))reached.add(i);});if(reached.size!==c.tiles.length)fail('Island land must be connected.');
 return c;
}
export function adjacent(c,a,b){const x=c.tiles[a],y=c.tiles[b];return Math.max(Math.abs(x.q-y.q),Math.abs(x.r-y.r),Math.abs(x.q+x.r-y.q-y.r))===1;}
function random(s){s.rng=(Math.imul(s.rng,1664525)+1013904223)>>>0;return s.rng/4294967296;}
function produce(c,s){s.roll=1+Math.floor(random(s)*6);const p=s.turn%2;s.choiceNeeded=true;s.log.push('Roll '+s.roll+'.');c.tiles.forEach((t,i)=>{if(t.number===s.roll&&s.owners[i]!==null){s.resources[s.owners[i]][t.resource]+=s.levels[i];if(s.owners[i]===p)s.choiceNeeded=false;s.log.push(c.playerNames[s.owners[i]]+' gained '+s.levels[i]+' '+t.resource+'.');}});if(s.choiceNeeded)s.log.push('Active player received no production: choose one resource before acting.');}
export function newSettlement(c,seed=1){const s={turn:0,scores:[1,1],owners:c.tiles.map(()=>null),levels:c.tiles.map(()=>0),resources:[0,1].map(()=>({wood:2,brick:2,grain:2,ore:1})),roads:[],roll:0,choiceNeeded:false,finished:false,winner:null,seed,rng:seed>>>0,actions:[],log:[]};c.starts.forEach((i,p)=>{s.owners[i]=p;s.levels[i]=1;});produce(c,s);return s;}
const cost={build:{wood:1,brick:1,grain:1},upgrade:{grain:2,ore:2}};
const afford=(bag,cost)=>Object.entries(cost).every(([r,n])=>bag[r]>=n);
export function settlementActions(c,s){if(s.finished)return [];const p=s.turn%2,b=s.resources[p];if(s.choiceNeeded)return RESOURCES.map(resource=>({type:'harvest',resource}));const out=[];c.tiles.forEach((t,cell)=>{if(s.owners[cell]===null&&afford(b,cost.build)&&c.tiles.some((_,i)=>s.owners[i]===p&&adjacent(c,cell,i)))out.push({type:'build',cell});if(s.owners[cell]===p&&s.levels[cell]===1&&afford(b,cost.upgrade))out.push({type:'upgrade',cell});});for(const give of RESOURCES)if(b[give]>=3)for(const receive of RESOURCES)if(give!==receive)out.push({type:'trade',give,receive});return [...out,{type:'pass'}];}
export function applySettlement(c,state,a){if(!settlementActions(c,state).some(x=>Object.keys(x).length===Object.keys(a).length&&Object.keys(x).every(k=>x[k]===a[k])))fail('That island action is not legal.');const s=structuredClone(state),p=s.turn%2,b=s.resources[p];s.actions.push(structuredClone(a));if(a.type==='harvest'){b[a.resource]++;s.choiceNeeded=false;s.log.push(c.playerNames[p]+' chose 1 '+a.resource+'.');return s;}
 if(a.type==='build'||a.type==='upgrade'){for(const [r,n] of Object.entries(cost[a.type]))b[r]-=n;if(a.type==='build'){const from=c.tiles.findIndex((_,i)=>s.owners[i]===p&&adjacent(c,a.cell,i));s.roads.push({from,to:a.cell,owner:p});s.owners[a.cell]=p;s.levels[a.cell]=1;}else s.levels[a.cell]=2;s.scores[p]++;s.log.push(c.playerNames[p]+' '+(a.type==='build'?'settled':'upgraded')+' hex '+(a.cell+1)+' (+1 point).');}
 else if(a.type==='trade'){b[a.give]-=3;b[a.receive]++;s.log.push(c.playerNames[p]+' traded 3 '+a.give+' for 1 '+a.receive+'.');}else s.log.push(c.playerNames[p]+' passed.');
 s.turn++;if(s.scores[p]>=c.targetPoints||s.turn>=c.turnLimit){s.finished=true;s.winner=s.scores[0]===s.scores[1]?null:s.scores[0]>s.scores[1]?0:1;}else produce(c,s);return s;
}
export function settlementChoice(c,s){const p=s.turn%2,b=s.resources[p],actions=settlementActions(c,s);let best=null,score=-Infinity;for(const a of actions){let n=0;if(a.type==='build')n=50+(c.tiles[a.cell].resource==='grain'?3:2)+c.tiles.filter((_,i)=>s.owners[i]===null&&adjacent(c,a.cell,i)).length;if(a.type==='upgrade')n=45;if(a.type==='harvest')n=20-(b[a.resource]||0)*3+(a.resource==='wood'||a.resource==='brick'||a.resource==='grain'?3:0);if(a.type==='trade')n=10-b[a.receive]*3+b[a.give];if(a.type==='pass')n=-100;if(n>score){score=n;best=a;}}return best;}
export function settlementRules(c){return {
 setup:`Two players: ${c.playerNames.join(' and ')}. Place the numbered hexes as shown. Each player starts with one settlement on their marked hex (${c.starts.map(i=>i+1).join(' and ')}), worth 1 point. Give each player 2 wood, 2 brick, 2 grain and 1 ore. Use a pencil ledger for an unlimited resource bank. Buildings occupy hex centers, not corners. A settlement gives 1 point and produces 1 resource; a city gives 2 points and produces 2. ${c.playerNames[0]} starts. You need one household six-sided die.`,
 turns:`At the start of every turn roll one six-sided die. Every occupied hex matching that number produces its named resource for its owner, even on the rival's turn. Cities produce two. If the active player received no production, they choose one resource from the bank. Then take exactly ONE action: build a settlement on an empty hex sharing an edge with a hex containing your settlement or city (pay 1 wood + 1 brick + 1 grain); upgrade your own settlement to a city (pay 2 grain + 2 ore); trade 3 identical resources for 1 different resource at the bank; or pass. A new settlement includes its connecting road, so roads do not need a separate action or cost. Trading uses the entire action. Resources and pieces are unlimited; use additional paper markers if needed. No robber, player-to-player trades, distance rule or intersection building is used in this original island game.`,
 scoring:'Settlements are worth 1 point each, cities 2. Building or upgrading adds 1 point. Resources and roads do not score. Ownership stays until the end. Keep each player’s resource counts public.',
 victory:`The first player to reach ${c.targetPoints} points wins immediately after their action. Otherwise finish after ${c.turnLimit} total turns; the higher score wins and tied points share victory. Swap first player for a rematch. The digital game applies these same rules; target duration is a design estimate until tested with people.`};}
